426	func transferParamsSig(req TransferRequest) string {
427		b, _ := json.Marshal(struct {
428			Kind          string `json:"kind"`
429			ItemID        string `json:"item_id"`
430			ExpectedOwner string `json:"expected_owner"`
431			ExpectedVer   int64  `json:"expected_version"`
432			ToID          string `json:"to_id"`
433			Reason        string `json:"reason"`
434		}{"transfer", req.ItemID, req.ExpectedOwner, req.ExpectedVer, req.ToID, req.Reason})
435		return string(b)
436	}
