438	// Transfer 由当前持有人发起转让。接收人必须已登记、可用且不同于当前
439	// 持有人；请求必须给出期望持有人与期望版本，藏品不存在或持有人/版本
440	// 不符时返回业务拒绝且不改变任何状态。同一 (操作者, 请求号) 的相同
441	// 请求重复提交（即使藏品后来已易手）返回首次结果。
442	func (r *Registry) Transfer(req TransferRequest) (TransferResult, error) {
443		if err := req.validatePresent(); err != nil {
444			return TransferResult{}, err
445		}
446		r.mu.Lock()
447		defer r.mu.Unlock()
448		if err := r.checkOpen(); err != nil {
449			return TransferResult{}, err
450		}
451	
452		key := requestKey(req.Operator, req.RequestID)
453		sig := transferParamsSig(req)
454		if prev, ok := r.state.Requests[key]; ok {
455			return r.replayTransfer(prev, sig)
456		}
457	
458		bizErr := r.checkTransfer(req)
459		if bizErr != nil {
460			if !isValidationErr(bizErr) {
461				// 状态类业务拒绝（持有人/版本不符、账户停用、收发同人等）
462				// 占用请求号并落盘，相同参数重提永远返回这一次拒绝。
463				r.state.Requests[key] = request{
464					Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
465					Params: sig, Rejected: true, Reason: errCode(bizErr),
466					ItemID: req.ItemID,
467				}
468				_ = r.commit()
469			}
470			// 藏品或账户不存在等校验错误不占用请求号，也不改变持有或历史。
471			return TransferResult{ItemID: req.ItemID, Err: bizErr}, bizErr
472		}
473	
474		h := r.state.Holdings[req.ItemID]
475		seq := r.state.NextSeq + 1
476		r.state.NextSeq = seq
477		from := h.OwnerID
478		fromVer := h.Version
479		h.OwnerID = req.ToID
480		h.Version = fromVer + 1
481		r.state.Holdings[req.ItemID] = h
482		r.state.History = append(r.state.History, historyEntry{
483			Seq: seq, Kind: "transfer", ItemID: req.ItemID, Operator: req.Operator,
484			Reason: req.Reason, RequestID: req.RequestID,
485			FromID: from, ToID: req.ToID, FromVersion: fromVer, ToVersion: fromVer + 1,
486		})
487		r.state.Requests[key] = request{
488			Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
489			Params: sig, ItemID: req.ItemID, FromID: from, ToID: req.ToID,
490			Version: fromVer + 1, TxSeq: seq,
491		}
492		if err := r.commit(); err != nil {
493			return TransferResult{}, err
494		}
495		return TransferResult{ItemID: req.ItemID, FromID: from, ToID: req.ToID,
496			Version: fromVer + 1, TxSeq: seq}, nil
497	}
498	
499	func (r *Registry) checkTransfer(req TransferRequest) error {
500		h, ok := r.state.Holdings[req.ItemID]
501		if !ok {
502			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
503				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
504			}
505			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
506		}
507		op, ok := r.state.Accounts[req.Operator]
508		if !ok {
509			return fmt.Errorf("%w: 操作者账户 %s", ErrNotFound, req.Operator)
510		}
511		if !op.Active {
512			return fmt.Errorf("%w: 操作者账户 %s", ErrAccountInactive, req.Operator)
513		}
514		to, ok := r.state.Accounts[req.ToID]
515		if !ok {
516			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
517		}
518		if !to.Active {
519			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
520		}
521		if req.ToID == h.OwnerID {
522			return fmt.Errorf("%w: 接收人 %s 已是当前持有人", ErrSameAccount, req.ToID)
523		}
524		// 期望持有人或期望版本不符，包括发起人并非当前持有人的情况。
525		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
526			req.Operator != h.OwnerID {
527			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d", ErrConflict,
528				req.ItemID, h.OwnerID, h.Version)
529		}
530		return nil
531	}
