405		if err != nil {
406			t.Fatal(err)
407		}
408		// 后续真实流转使藏品到了 carol 手中，版本 3
409		if _, err := r.Transfer(xferReq("bob", "i1", "carol", 2, "t2")); err != nil {
410			t.Fatal(err)
