func TestTransferRoyaltyFullRange(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	royaltyWorld(t, r)
	mustSetRoyalty(t, r, "rs1",
		RoyaltyShare{AccountID: "carol", Rate: 10000}, // 100%
	)
