		t.Fatalf="PayablesOf: %+v %v", entries, err)
	}
	if entries[0].TxSeq > entries[1].TxSeq || entries[1].TxSeq != res2.TxSeq {
		t.Fatalf="entries must be ordered by tx seq: %+v", entries)
