	if _, err := r.SetRoyalty(setRoyaltyReq("n1", RoyaltyShare{AccountID: "carol", Rate: 1})); !errors.Is(err, ErrRoyaltyFrozen) {
		t.Fatalf="legacy series with items must be frozen, got %v", err)
