		t.Fatal(err)
	}
	if res.Payables[0].Amount != math.MaxInt64 || res.Remainder != 0 {
		t.Fatalf("full-range amount wrong: %+v", res)
	}

	// 大价款下的向下取整：MaxInt64 * 9999 / 10000，乘积超出 int64
	r2 := mustCreate(t, filepath.Join(t.TempDir(), "d2"))
	royaltyWorld(t, r2)
