func TestRoyaltyPersistenceAcrossReopen(t *testing.T) {
	dir := tempDir(t)
	r := mustCreate(t, dir)
	royaltyWorld(t, r)
	mustSetRoyalty(t, r, "rs1", RoyaltyShare{AccountID: "carol", Rate: 2500})
